from jsonb_to_recordset($json$[{"id":"che-ek-161","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Absolute temperature enters the Nernst equation because","options":["the $RT/nF$ prefactor, and therefore the size of the $\\log Q$ correction, depends on $T$","Faraday's constant itself is proportional to $T$","$n$ changes with temperature","standard potentials are defined only at 0 K"],"answer_index":0,"explanation":"At higher $T$ a given $Q$ shifts $E$ farther from $E^\\circ$. $E^\\circ$ itself may also change with $T$, but that is a separate effect.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-162","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A Daniell cell with $E^\\circ = 1.10\\ \\mathrm{V}$ has $[\\mathrm{Zn^{2+}}] = 0.10\\ \\mathrm{M}$ and $[\\mathrm{Cu^{2+}}] = 1.0\\ \\mathrm{M}$. $E$ at 298 K is nearest","options":["$1.13\\ \\mathrm{V}$","$1.07\\ \\mathrm{V}$","$0.10\\ \\mathrm{V}$","$1.16\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E = 1.10 - (0.059/2)\\log(0.10/1.0) = 1.10 + 0.0295 = 1.13\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-163","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $\\mathrm{Cu}|\\mathrm{Cu^{2+}}(0.010\\ \\mathrm{M})||\\mathrm{Cu^{2+}}(1.0\\ \\mathrm{M})|\\mathrm{Cu}$ at 298 K the EMF is","options":["$0.059\\ \\mathrm{V}$","$0.029\\ \\mathrm{V}$","$0.118\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E^\\circ = 0$ and $n = 2$, so $E = (0.059/2)\\log(1.0/0.010) = 0.0295 \\times 2 = 0.059\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-164","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Take $E^\\circ(\\mathrm{Zn^{2+}/Zn}) = -0.76\\ \\mathrm{V}$. At $[\\mathrm{Zn^{2+}}] = 0.010\\ \\mathrm{M}$ and 298 K the zinc electrode potential is nearest","options":["$-0.82\\ \\mathrm{V}$","$-0.70\\ \\mathrm{V}$","$-0.76\\ \\mathrm{V}$","$+0.76\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E = -0.76 + (0.059/2)\\log(0.010) = -0.76 + 0.0295\\times(-2) = -0.82\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-165","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Starting from a standard Daniell cell, diluting only the Cu$^{2+}$ half-cell tenfold at 298 K changes $E$ by about","options":["a decrease of $0.030\\ \\mathrm{V}$","an increase of $0.059\\ \\mathrm{V}$","a decrease of $0.76\\ \\mathrm{V}$","no change, because $E^\\circ$ is fixed"],"answer_index":0,"explanation":"$Q$ rises by 10, so $\\Delta E = -(0.059/2)\\log 10 \\approx -0.030\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-166","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hydrogen electrode ($p_{\\mathrm{H_2}} = 1\\ \\mathrm{bar}$) dipping into $0.0010\\ \\mathrm{M}$ HCl at 298 K develops a potential of","options":["$-0.177\\ \\mathrm{V}$","$0.000\\ \\mathrm{V}$","$-0.059\\ \\mathrm{V}$","$+0.177\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$[\\mathrm{H}^+] = 10^{-3}$, so $E = 0.059\\log(10^{-3}) = -0.177\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-167","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $\\mathrm{Zn}|\\mathrm{Zn^{2+}}(0.10\\ \\mathrm{M})||\\mathrm{Cu^{2+}}(0.0010\\ \\mathrm{M})|\\mathrm{Cu}$ with $E^\\circ = 1.10\\ \\mathrm{V}$, $E$ at 298 K is","options":["$1.041\\ \\mathrm{V}$","$1.159\\ \\mathrm{V}$","$0.041\\ \\mathrm{V}$","$1.10\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$Q = 0.10/0.0010 = 100$; $E = 1.10 - (0.059/2)\\log 100 = 1.10 - 0.059 = 1.041\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-168","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A Cu concentration cell shows $E = 0.0295\\ \\mathrm{V}$ at 298 K. The ratio $[\\mathrm{Cu^{2+}}]_{\\mathrm{cathode}}/[\\mathrm{Cu^{2+}}]_{\\mathrm{anode}}$ is","options":["10","2","100","0.10"],"answer_index":0,"explanation":"$E = (0.059/2)\\log(c_c/c_a) = 0.0295$ implies $\\log(c_c/c_a) = 1$, so the concentration ratio is 10.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"nernst","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-169","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Faraday's first law of electrolysis states that the mass deposited is proportional to the","options":["quantity of electricity passed through the electrolyte","square of the applied voltage only","volume of the voltameter","atmospheric pressure in the laboratory"],"answer_index":0,"explanation":"$m = ZQ = ZIt$. Charge (current × time) fixes how much material is liberated.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-170","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Faraday's second law compares two electrolytes carrying the same charge and says the liberated masses are proportional to their","options":["chemical equivalent masses (molar mass / n-factor)","densities in the solid state","boiling points","specific conductivities"],"answer_index":0,"explanation":"Equal charge liberates equal numbers of equivalents, so $m_1/m_2 = E_1/E_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
